export interface ApeaMateriality {
  overVotingMagnitude: number;
  declaredMargin: number;
  ratioPct: number | null;
  note: string;
}

export interface ApeaForensicCounts {
  [status: string]: number;
}

export interface ApeaAudit {
  code: string;
  state: string;
  year: number;
  title: string;
  methodology: string;
  publicIntegrityCategory: string;
  total: number;
  compliant: number;
  noncompliant: number;
  excluded: number;
  assessable: number;
  forensicCounts: ApeaForensicCounts;
  materiality: ApeaMateriality;
  spreadVerdict?: string;
  pu: {
    headers: string[];
    rows: any[][];
    rowsGzipBase64?: string;
  };
  meta: {
    bucketCol: string;
    legalCol: string | null;
    forensicCol: string | null;
    reasonCol: string | null;
  };
  publicIntegrityNote?: string;
  collationCount?: number;
}

export interface ApeaReportDetail {
  findings?: string[];
  dashboard?: {
    tech: [string, string, string, string][];
    puc: [string, string, string, string][];
    coll: [string, string, string, string][];
  };
  coverageSummary?: [string, string][];
  triggers?: [string, number][];
  triggerNote?: string;
  geo?: {
    primary: string;
    secondary?: string;
    note?: string;
  };
  featuredCase?: {
    title: string;
    code: string;
    bvas: number;
    ec8a: number;
    ec8b: number;
    delta: string;
    note: string;
  };
  materialityLabel?: string;
  stress?: {
    title?: string;
    rows?: [string, string][];
    conclusion?: string;
  };
  coverage?: [string, string, string][];
  limitations?: string[];
}

export interface ApeaPublicReportFile {
  uri: string;
  name: string;
  label: string;
}

